1	package main
2	
3	import (
4		"context"
5		"crypto/rand"
6		_ "embed"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"os"
16		"os/signal"
17		"path/filepath"
18		"strings"
19		"sync"
20		"syscall"
21		"time"
22	)
23	
24	const product = "ScoreArena"
25	const resourceName = "rooms"
26	
27	//go:embed index.html
28	var indexPage []byte
29	
30	// roomConfig 是创建房间时接受的配置。字段是否缺失在 parseRoomFields 中显式检查，
31	// 不允许把漏填的值悄悄替换为默认值。
32	type roomConfig struct {
33		Name        string `json:"name"`
34		Game        string `json:"game"`
35		Capacity    int    `json:"capacity"`
36		TurnSeconds int    `json:"turnSeconds"`
37	}
