39	type room struct {
40		ID          string `json:"id"`
41		Name        string `json:"name"`
42		Game        string `json:"game"`
43		Capacity    int    `json:"capacity"`
44		TurnSeconds int    `json:"turnSeconds"`
45		Status      string `json:"status"`
46		Visibility  string `json:"visibility"`
47		CreatedAt   string `json:"createdAt"`
48	}
