53	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
54	function startServer(t, dataDir) {
55	  const proc = spawn(
56	    serverBin,
57	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
58	    { stdio: ['ignore', 'pipe', 'inherit'] },
59	  );
60	  t.after(() => { proc.kill('SIGKILL'); });
61	  return new Promise((resolve, reject) => {
62	    let buf = '';
63	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
64	    proc.stdout.on('data', (chunk) => {
65	      buf += chunk.toString();
66	      const m = buf.match(/listening on (http:\/\/\S+)/);
67	      if (m) {
68	        clearTimeout(timer);
69	        resolve(m[1]);
70	      }
71	    });
72	    proc.on('exit', (code) => {
73	      clearTimeout(timer);
74	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
75	    });
76	  });
77	}
