393	  const list = await readListArea(page);
394	  assert.equal(list.errorText, '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。');
395	  assert.equal(list.emptyText, null, '列表刷新失败时不得显示“还没有房间记录”');
396	  assert.ok(!list.text.includes('还没有房间记录'), '列表刷新失败时不得显示空列表文案');
397	  assert.ok(!list.hasTable, '列表刷新失败时不应展示旧表格冒充最新列表');
398	
399	  // 成功提示不被覆盖为失败：创建没有被说成失败，用户无需再次创建。
400	  const msgAfter = await readMessage(page);
401	  assert.ok(msgAfter.className.includes('ok'), '列表刷新失败不应把已完成的创建说成失败');
402	  assert.equal(msgAfter.text, msg.text, '成功提示与编号应保留');
403	
404	  // 服务端确实已保存本次创建（证明创建本身成功，只是刷新失败）。
405	  const res = await fetch(baseURL + '/api/rooms');
406	  assert.equal(res.status, 200);
407	  const data = await res.json();
408	  assert.equal(data.rooms.length, 3, '服务端应已保存新房间');
409	  assert.equal(data.rooms[2].id, shownId, '服务端保存的编号应与页面提示一致');
410	});
411	
412	// 提交等待期间创建按钮暂时不可用，请求完成后恢复可用，页面不停在等待状态。
413	test('提交等待期间创建按钮不可用，请求完成后恢复', { timeout: 60000 }, async (t) => {
414	  const { page } = await setupPage(t);
415	
416	  // 挂起创建请求，直到测试手动放行，以观察等待期间的按钮状态。
417	  await page.setRequestInterception(true);
418	  let releasePost;
419	  const postHeld = new Promise((resolve) => { releasePost = resolve; });
420	  page.on('request', (req) => {
421	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
422	      postHeld.then(() => req.continue());
423	    } else {
424	      req.continue();
425	    }
426	  });
427	
428	  await fillGomokuForm(page, '等待中的房间', 0);
429	  await page.click('#submit');
430	
431	  // 等待期间按钮不可用，且不是瞬间恢复。
432	  await page.waitForFunction(
433	    () => document.getElementById('submit').disabled,
434	    { timeout: 5000 },
435	  );
436	  await new Promise((resolve) => setTimeout(resolve, 300));
437	  assert.equal((await readFormState(page)).submitDisabled, true, '提交等待期间按钮应保持不可用');
438	
439	  // 放行请求：完整成功后按钮恢复可用，不停在等待状态。
440	  releasePost();
441	  await waitForMessageKind(page, 'ok');
442	  await waitForRowCount(page, 3);
443	  await page.waitForFunction(
444	    () => !document.getElementById('submit').disabled,
445	    { timeout: 10000 },
446	  );
447	  assert.equal((await readFormState(page)).submitDisabled, false, '完成后按钮应恢复可用');
448	});
